import numpy as np
def f(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    # template: non-zero non-eight cells cluster
    tc=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,8)]
    rs=[r for r,c in tc]; cs=[c for r,c in tc]
    ttop,tbot=min(rs),max(rs); tleft,right=min(cs),max(cs)
    T=np.array([[g[r][c] for c in range(tleft,right+1)] for r in range(ttop,tbot+1)])
    R=np.rot90(T,k=-1)  # CW rotation
    out=[row[:] for row in g]
    oc=[(r,c) for r in range(h) for c in range(w) if g[r][c]==8]
    seen=set(); objs=[]
    for cell in sorted(oc):
        r,c=cell
        if (r,c) in seen: continue
        stack=[(r,c)]; comp=[]
        while stack:
            a,b=stack.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); comp.append((a,b))
            for da in(-1,0,1):
                for db in(-1,0,1):
                    x,y=a+da,b+db
                    if 0<=x<h and 0<=y<w and g[x][y]==8 and (x,y) not in seen: stack.append((x,y))
        objs.append(comp)
    for o in objs:
        rs=[r for r,c in o]; cs=[c for r,c in o]
        top,left=min(rs),min(cs); bh=max(rs)-top+1; bw=max(cs)-left+1
        for i in range(bh):
            for j in range(bw):
                v=R[i%R.shape[0]][j%R.shape[1]]
                if v!=0:
                    for a in(0,1):
                        for b in(0,1):
                            rr,cc=top+i+a,left+j+b
                            if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out
